import io, pickle, urllib.request
from model_selection import registry, metrics

SAFE = {
    ("collections", "OrderedDict"),
    ("builtins", "dict"), ("builtins", "list"), ("builtins", "tuple"),
    ("builtins", "set"), ("builtins", "frozenset"), ("builtins", "str"),
    ("builtins", "int"), ("builtins", "float"), ("builtins", "bytes"),
    ("builtins", "bytearray"), ("builtins", "bool"), ("builtins", "complex"),
}

class RestrictedUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        if module.startswith("numpy"):
            return super().find_class(module, name)
        if (module, name) in SAFE:
            return super().find_class(module, name)
        raise pickle.UnpicklingError(f"blocked unsafe global: {module}.{name}")

scores = []
for sub_id, url in registry.iter_submissions(registry.fetch_manifest()):
    data = urllib.request.urlopen(url).read()
    obj = RestrictedUnpickler(io.BytesIO(data)).load()
    scores.append((sub_id, obj["val_accuracy"]))
    print(f"{sub_id}: val_accuracy={obj['val_accuracy']!r} id_in_artifact={obj.get('id')}")

board = metrics.leaderboard(scores)
print()
print(metrics.format_leaderboard(board))
print()
print("winner:", metrics.winner(board))
EOF","workdir":"/testbed"}

